#!/bin/sh
# Print the three most frequent client addresses in access.log.  The record
# number saved in first[] makes equal counts sort by order of first appearance.
LC_ALL=C awk '
    {
        ip = $1
        if (!(ip in count)) {
            count[ip] = 0
            first[ip] = NR
            addresses[++n] = ip
        }
        count[ip]++
    }
    END {
        limit = (n < 3 ? n : 3)
        for (rank = 1; rank <= limit; rank++) {
            chosen = ""
            for (i = 1; i <= n; i++) {
                ip = addresses[i]
                if (used[ip])
                    continue
                if (chosen == "" || count[ip] > count[chosen] || \
                    (count[ip] == count[chosen] && first[ip] < first[chosen]))
                    chosen = ip
            }
            print chosen
            used[chosen] = 1
        }
    }
' access.log
